const fs=require('node:fs'),path=require('node:path'),http=require('node:http'),assert=require('node:assert/strict'),pw=require('playwright');
const engine=process.argv[2]||'chromium',root=process.cwd(),out=path.resolve('qa-education-'+engine,'learning-20261030');let browser,server;const errors=[];
(async()=>{
 fs.mkdirSync(out,{recursive:true});server=http.createServer((req,res)=>{let f=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname);if(fs.existsSync(f)&&fs.statSync(f).isDirectory())f=path.join(f,'index.html');if(!f.startsWith(root+path.sep)||!fs.existsSync(f)||!fs.statSync(f).isFile())return res.writeHead(404).end();res.setHeader('Content-Type',({'.js':'application/javascript','.html':'text/html','.css':'text/css'})[path.extname(f)]||'application/octet-stream');res.end(fs.readFileSync(f));});await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port;
 browser=await pw[engine].launch(process.env.STUDENTS_BROWSER_EXECUTABLE?{executablePath:process.env.STUDENTS_BROWSER_EXECUTABLE}:{});const context=await browser.newContext({viewport:{width:1440,height:1000},serviceWorkers:'block'});await context.route('**/*',r=>new URL(r.request().url()).origin===base?r.continue():r.abort());const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));let views=0;
 const tab=async name=>{await page.locator('[data-tab="'+name+'"]').click();await page.locator('[data-pane="'+name+'"]:not([hidden])').waitFor();};
 for(const width of [1440,390,320]){await page.setViewportSize({width,height:1000});await page.goto(base+'/students/?width='+width+'#progress');await page.locator('.learning-chapter').first().waitFor();assert.equal(await page.locator('.learning-chapter').count(),16);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Progress reflow '+width);await page.screenshot({path:path.join(out,'progress-'+width+'.png'),fullPage:true});views++;
  await tab('selftest');await page.locator('#test-none').click();await page.locator('[name="test-chapter"][value="1"]').check();await page.locator('#test-count').fill('3');await page.getByRole('button',{name:'Start self-test',exact:true}).click();await page.locator('#test-answer').waitFor();assert.equal(await page.locator('#learning-selftest details,#learning-selftest .learning-resources').count(),0);assert.ok(!/Worked solution|Expected:/.test(await page.locator('#learning-selftest').innerText()));const t=await page.evaluate(()=>JSON.parse(localStorage.getItem(MT_LEARNING_ENGINE.key)).activeTest);
  await page.locator('#test-answer').fill(String(t.items[0].expected));await page.locator('#test-next').click();await page.locator('#test-answer').fill('unfinished');await page.reload();await page.locator('#test-answer').waitFor();assert.equal(await page.locator('#test-answer').inputValue(),'unfinished');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Test reflow '+width);await page.locator('#test-review').click();await page.locator('#test-submit').click();await page.locator('#test-result-title').waitFor();assert.match(await page.locator('#test-result-title').innerText(),/1 \/ 3/);assert.equal(await page.locator('.test-result details').count(),3);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Results reflow '+width);await page.screenshot({path:path.join(out,'result-'+width+'.png'),fullPage:true});views++;
  await page.goto(base+'/students/?practice='+width+'#exercise/practice-c03-q16');await page.locator('#exercise-question[data-exercise-id="practice-c03-q16"]').waitFor();await page.locator('#exercise-answer').fill('123,4');await page.locator('#exercise-resources a[href*="interactive.html"]').first().click();await page.locator('#module-quick').selectOption('transient');await page.locator('.workspace-toolbar a').filter({hasText:'Back to exercise'}).click();await page.locator('#exercise-answer').waitFor();assert.equal(await page.locator('#exercise-answer').inputValue(),'123,4');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'Exercise reflow '+width);views++;
 }
 // Manual-activation tabs: arrows move focus, Enter activates the focused tab.
 await tab('formulas');await page.locator('[data-tab="formulas"]').focus();await page.keyboard.press('ArrowRight');assert.equal(await page.evaluate(()=>document.activeElement.dataset.tab),'symbols');assert.equal(await page.locator('[data-tab="formulas"]').getAttribute('aria-selected'),'true');await page.keyboard.press('Enter');assert.equal(await page.locator('[data-tab="symbols"]').getAttribute('aria-selected'),'true');await page.keyboard.press('End');assert.equal(await page.evaluate(()=>document.activeElement.dataset.tab),'sheet');await page.keyboard.press('Home');assert.equal(await page.evaluate(()=>document.activeElement.dataset.tab),'formulas');
 await tab('calculators');await page.locator('#calc-selector').selectOption('ohms-law');const input=page.locator('#calc-fields input').first();await input.fill('');assert.equal(await input.getAttribute('aria-invalid'),'true');assert.equal(await page.locator('#calc-output [role=alert]').count(),1);await input.fill('12');assert.equal(await input.getAttribute('aria-invalid'),'false');
 // Verify actual theme text/focus colors against both panel surfaces.
 const contrast=[];for(const theme of ['maritime','bridge']){await page.locator('#student-theme').selectOption(theme);const values=await page.evaluate(()=>{const css=getComputedStyle(document.documentElement),rgb=s=>{const c=document.createElement('span');c.style.color=s;document.body.append(c);const v=getComputedStyle(c).color.match(/[\d.]+/g).slice(0,3).map(Number);c.remove();return v;};return Object.fromEntries(['text','muted','accent','gold','good','bad','panel','raised'].map(k=>[k,rgb(css.getPropertyValue('--'+k))]));});const luminance=a=>a.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((s,v,i)=>s+v*[.2126,.7152,.0722][i],0);for(const text of ['text','muted','accent','good','bad','gold'])for(const bg of ['panel','raised']){const a=luminance(values[text]),b=luminance(values[bg]),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);assert.ok(ratio>=4.5,theme+'/'+text+'/'+bg+' '+ratio);contrast.push({theme,text,bg,ratio});}}
 await page.goto(base+'/students/chapters.html');assert.equal(await page.locator('a.skip-link').count(),1);if(engine==='webkit'){await page.locator('a.skip-link').focus();}else{await page.keyboard.press('Tab');}assert.equal(await page.evaluate(()=>document.activeElement.className),'skip-link');await page.keyboard.press('Enter');assert.equal(await page.evaluate(()=>document.activeElement.tagName),'MAIN');
 await page.goto(base+'/students/model-lab.html?keyboard=1#beam');const svg=page.locator('#model-chart');await svg.waitFor();const original=await svg.getAttribute('viewBox');await svg.focus();await page.keyboard.press('+');const zoomed=await svg.getAttribute('viewBox');assert.notEqual(zoomed,original);await page.keyboard.press('ArrowRight');assert.notEqual(await svg.getAttribute('viewBox'),zoomed);await page.keyboard.press('0');assert.equal(await svg.getAttribute('viewBox'),original);const bar=svg.locator('xpath=preceding-sibling::*[1]'),pans=svg.locator('xpath=following-sibling::div[contains(@class,"diagram-pan-tools")][1]');assert.ok(await pans.getByRole('button',{name:'Pan left',exact:true}).isDisabled());await bar.getByRole('button',{name:'Zoom +',exact:true}).click();assert.ok(await pans.getByRole('button',{name:'Pan left',exact:true}).isEnabled());await pans.getByRole('button',{name:'Pan left',exact:true}).click();assert.ok((await svg.getAttribute('aria-describedby')).length>0);
 await page.getByText('Numerical data and units',{exact:true}).click();const table=page.locator('.table-wrap').filter({has:page.locator('table')}).first();assert.equal(await table.getAttribute('tabindex'),'0');assert.equal(await table.getAttribute('role'),'region');assert.ok(await table.getAttribute('aria-label'));await page.keyboard.press('Tab');await table.focus();assert.equal(await table.evaluate(n=>getComputedStyle(n).outlineStyle),'solid');await page.emulateMedia({reducedMotion:'reduce'});assert.equal(await page.evaluate(()=>getComputedStyle(document.documentElement).scrollBehavior),'auto');
 await page.setViewportSize({width:1280,height:720});for(const id of ['trim','crank']){await page.goto(base+'/students/examples.html?axis='+id+'#'+id);await page.locator('#presentation-toggle').click();await page.waitForFunction(()=>document.getElementById('chart').style.getPropertyValue('--teaching-chart-height'));await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));assert.ok(await page.locator('#chart').evaluate(n=>n.getBoundingClientRect().bottom<=innerHeight+2),'Laptop presentation lower axis '+id);}
 assert.deepEqual(errors,[]);fs.writeFileSync(path.join(out,'results.json'),JSON.stringify({status:'PASS',engine,responsiveViews:views,contrast,scope:'Progress/test/exercise reflow, answer and test reload, return from model, deferred solutions, manual tabs, field errors, skip link, diagram pan/zoom, data-table access, focus and reduced motion.'},null,2));console.log(JSON.stringify({status:'PASS',engine,responsiveViews:views,contrastPairs:contrast.length}));await context.close();
})().catch(e=>{console.error(e);process.exitCode=1;}).finally(async()=>{await browser?.close();await new Promise(r=>server?server.close(r):r());});
